head.script:
scwin.checkStatusSubtotal = function(status) {
    return WebSquare.wUnit.getJq('tr[data-subtotalrowindex = 118]')[0].style.display == status;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();

    WebSquare.wUnit.addCommand("pause", "2000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_equip_detail_scrollY_div').scrollTop = 1800");
    WebSquare.wUnit.addCommand("pause", "1000");

    WebSquare.wUnit.addCommand("assert", "scwin.checkStatusSubtotal('')", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_equip_detail_scrollY_div').scrollTop = 0");
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("assert", "scwin.checkStatusSubtotal('none')", "true");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_equip_detail_scrollY_div').scrollTop = 1800");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkStatusSubtotal('')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

